from solution import exchange
import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference(lst1, lst2):
    odd_needed = sum(1 for x in lst1 if x % 2 != 0)
    even_available = sum(1 for x in lst2 if x % 2 == 0)
    return "YES" if odd_needed <= even_available else "NO"


# --- concrete examples from spec ---

def test_spec_example_1():
    assert exchange([1, 2, 3, 4], [1, 2, 3, 4]) == "YES"


def test_spec_example_2():
    assert exchange([1, 2, 3, 4], [1, 5, 3, 4]) == "NO"


# --- explicit defect-hunting examples: lengths differ ---

def test_different_lengths_lst1_longer_but_enough_evens():
    # lst1 has 1 odd, lst2 has 2 evens -> YES per spec
    assert exchange([1, 2, 3], [2, 4]) == "YES"


def test_different_lengths_lst2_longer_and_enough_evens():
    # lst1 has 2 odds, lst2 has 2 evens -> YES per spec
    assert exchange([1, 3], [2, 4, 6, 8, 11]) == "YES"


def test_different_lengths_lst1_already_even():
    # lst1 already all even -> YES regardless of lst2 contents/length
    assert exchange([2, 4], [1, 3, 5]) == "YES"


def test_different_lengths_lst1_already_even_singleton():
    assert exchange([2], [1, 3, 5, 7, 9]) == "YES"


def test_different_lengths_insufficient_evens():
    # lst1 has 3 odds, lst2 has 1 even -> NO
    assert exchange([1, 3, 5], [2, 7]) == "NO"


def test_singleton_odd_with_singleton_even():
    assert exchange([1], [2]) == "YES"


def test_singleton_odd_with_singleton_odd():
    assert exchange([1], [3]) == "NO"


def test_singleton_even_with_singleton_odd():
    assert exchange([2], [1]) == "YES"


def test_lst1_all_even_always_yes_equal_length():
    assert exchange([2, 4, 6], [1, 3, 5]) == "YES"


def test_lst2_all_odd_lst1_has_odd_is_no():
    assert exchange([2, 1], [1, 3, 5]) == "NO"


def test_negative_numbers():
    # -2, -4 are even; -1, -3 are odd
    assert exchange([-1, -2, -3], [-4, -6]) == "YES"
    assert exchange([-1, -3], [-5, -7]) == "NO"
    assert exchange([-2, -4], [-1, -3]) == "YES"


def test_zero_is_even():
    assert exchange([0, 1], [1, 3, 5]) == "NO"
    assert exchange([1, 3], [0, 2]) == "YES"
    assert exchange([0, 2], [1]) == "YES"


# --- property-based tests vs reference model ---

@given(
    st.lists(st.integers(min_value=-100, max_value=100), min_size=1, max_size=8),
    st.lists(st.integers(min_value=-100, max_value=100), min_size=1, max_size=8),
)
def test_property_matches_reference_model(lst1, lst2):
    assert exchange(list(lst1), list(lst2)) == reference(lst1, lst2)


@given(
    st.lists(st.integers(min_value=-50, max_value=50).filter(lambda x: x % 2 == 0), min_size=1, max_size=6),
    st.lists(st.integers(min_value=-50, max_value=50), min_size=1, max_size=6),
)
def test_property_lst1_already_even_always_yes(lst1, lst2):
    assert exchange(list(lst1), list(lst2)) == "YES"


@given(
    st.lists(st.integers(min_value=-50, max_value=50), min_size=1, max_size=6),
    st.lists(st.integers(min_value=-50, max_value=50).filter(lambda x: x % 2 != 0), min_size=1, max_size=6),
)
def test_property_lst2_all_odd_depends_only_on_lst1(lst1, lst2):
    expected = "YES" if all(x % 2 == 0 for x in lst1) else "NO"
    assert exchange(list(lst1), list(lst2)) == expected


@given(st.integers(min_value=1, max_value=6), st.integers(min_value=1, max_value=6))
def test_property_exact_boundary_counts(n_odds, n_evens):
    # lst1 has exactly n_odds odds (plus one even to vary length),
    # lst2 has exactly n_evens evens.
    lst1 = [1] * n_odds + [2]
    lst2 = [2] * n_evens + [1]
    expected = "YES" if n_odds <= n_evens else "NO"
    assert exchange(list(lst1), list(lst2)) == expected


@given(
    st.lists(st.integers(min_value=-20, max_value=20), min_size=1, max_size=5),
    st.lists(st.integers(min_value=-20, max_value=20), min_size=1, max_size=5),
)
def test_property_result_is_only_yes_or_no(lst1, lst2):
    assert exchange(list(lst1), list(lst2)) in ("YES", "NO")


@given(
    st.lists(st.integers(min_value=-20, max_value=20), min_size=1, max_size=5),
    st.lists(st.integers(min_value=-20, max_value=20), min_size=1, max_size=5),
)
def test_property_adding_evens_to_lst2_monotonic(lst1, lst2):
    # Adding more evens to lst2 can only flip NO -> YES, never YES -> NO.
    base = exchange(list(lst1), list(lst2))
    extended = exchange(list(lst1), list(lst2) + [2, 4, 6])
    if base == "YES":
        assert extended == "YES"


@given(
    st.lists(st.integers(min_value=-20, max_value=20), min_size=1, max_size=5),
    st.lists(st.integers(min_value=-20, max_value=20), min_size=1, max_size=5),
)
def test_property_making_lst1_all_even_forces_yes(lst1, lst2):
    lst1_even = [x if x % 2 == 0 else x + 1 for x in lst1]
    assert all(x % 2 == 0 for x in lst1_even)
    assert exchange(list(lst1_even), list(lst2)) == "YES"
